<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForgePrintifyConnector\Preparation\{NativePortAdapter,RecoveryDiagnostics};
require_once __DIR__.'/../fixtures/printify-connector/stage34/companion-test-bootstrap.php';
require_once __DIR__.'/../fixtures/printify-connector/batch6/SyntheticNativeCore.php';
final class PrintifyCompanionBatch8Test extends TestCase {
 public function testRecoveryDiagnosticsNeverTurnUnknownIntoRetry():void {[$s]=(require __DIR__.'/../fixtures/printify-connector/batch5/fixture.php')();$c=new SyntheticNativeCore();$d=new RecoveryDiagnostics(new NativePortAdapter($c));$r=$d->snapshot($s,1);self::assertSame('UNRESOLVED_UNKNOWN',$r['state']);self::assertFalse($r['retry_permitted']);self::assertFalse($r['external_execution_authorized']);$c->fault='stale_recovery';self::assertSame('RECOVERY_REQUIRED',$d->snapshot($s,1)['state']);$c->fault='revoked';self::assertInstanceOf(WP_Error::class,$d->snapshot($s,1));self::assertSame(0,$c->writeCalls);self::assertTrue($c->safetyStop);self::assertStringContainsString('unavailable',$d->render($s,1));$c->fault='';self::assertStringContainsString('UNRESOLVED_UNKNOWN',$d->render($s,1));}
 private function store():array {require_once __DIR__.'/../fixtures/printify-connector/batch8/RecoveryStore.php';$dir=sys_get_temp_dir().'/df-recovery-'.bin2hex(random_bytes(8));mkdir($dir,0700);$this->paths[]=$dir;return [new SyntheticRecoveryStore($dir.'/state',$dir.'/anchor'),$dir];}
 private array $paths=[];
 protected function tearDown():void {foreach($this->paths as $p){foreach(glob($p.'/*')as $f)unlink($f);rmdir($p);}parent::tearDown();}
 public function testRestartRetainsPreparedReservedUnknownAndConflictWithoutRearming():void {[$s,$p]=$this->store();$s->initialize();$s->transition('a','PREPARE',1,100);$s=new SyntheticRecoveryStore($p.'/state',$p.'/anchor');self::assertSame('PREPARED',$s->inspect()['records']['a']['state']);$s->transition('a','RESERVE',1,100);$s=new SyntheticRecoveryStore($p.'/state',$p.'/anchor');self::assertSame('RESERVED',$s->inspect()['records']['a']['state']);$s->transition('a','EXPIRE',1,121);self::assertSame('UNKNOWN',$s->inspect()['records']['a']['state']);$s->transition('a','CONFLICT',1,122);self::assertSame('CONFLICTING',(new SyntheticRecoveryStore($p.'/state',$p.'/anchor'))->inspect()['records']['a']['state']);$this->expectException(RuntimeException::class);$s->transition('a','RESERVE',1,200);}
 /** @dataProvider storageFaults */
 public function testInterruptedPersistenceNeverProducesFalseAcknowledgement(string $fault):void {[$s,$p]=$this->store();$s->initialize();$s->fault=$fault;try{$s->transition('a','PREPARE',1,100);self::fail('No false acknowledgement');}catch(RuntimeException $e){self::assertNotSame('', $e->getMessage());}$s->fault='';if($fault==='journal_failure'){$this->expectException(RuntimeException::class);$s->inspect();}else self::assertSame($fault==='lost_ack'?1:0,$s->inspect()['revision']);}
 public static function storageFaults():array{return [['storage_failure'],['journal_failure'],['lost_ack']];}
 /** @dataProvider corruptions */
 public function testOneRootRollbackOrReceiptTamperingFailsClosed(string $fault):void {[$s,$p]=$this->store();$s->initialize();$old=file_get_contents($p.'/state');$anchor=file_get_contents($p.'/anchor');$s->transition('a','PREPARE',1,100);if($fault==='state')file_put_contents($p.'/state',$old);elseif($fault==='anchor')file_put_contents($p.'/anchor',$anchor);else{$r=json_decode(file_get_contents($p.'/state'),true);if($fault==='receipt')$r['events'][0]['hash']=str_repeat('0',64);else $r['records']['a']['state']='UNKNOWN';file_put_contents($p.'/state',json_encode($r));}$this->expectException(RuntimeException::class);$s->inspect();}
 public static function corruptions():array{return [['state'],['anchor'],['receipt'],['records']];}
 public function testAllRootRollbackCounterexampleRemainsExplicitlyUnprotected():void {[$s,$p]=$this->store();$s->initialize();$s->transition('a','PREPARE',1,100);$old=file_get_contents($p.'/state');$a=file_get_contents($p.'/anchor');$s->transition('a','RESERVE',1,100);$s->transition('all','EMERGENCY',1,101);file_put_contents($p.'/state',$old);file_put_contents($p.'/anchor',$a);self::assertSame('RESERVED',$s->transition('a','RESERVE',1,110)['records']['a']['state'],'Counterexample: both local roots restored can revive authority; production RECOVERY_BLOCKED');}
 public function testEmergencyGenerationInvalidatesOldPreparedAuthorityAndTracksUnknown():void {[$s]=$this->store();$s->initialize();$s->transition('a','PREPARE',1,100);$s->transition('a','RESERVE',1,100);$s->transition('all','EMERGENCY',1,101);self::assertSame('UNKNOWN',$s->inspect()['records']['a']['state']);self::assertSame(2,$s->inspect()['generation']);$this->expectException(RuntimeException::class);$s->transition('b','PREPARE',1,102);}
 public function testTwoWorkersHaveExactlyOneReservationWinner():void {[$s,$p]=$this->store();$s->initialize();$s->transition('a','PREPARE',1,100);$pipes=[];$procs=[];for($i=0;$i<2;$i++)$procs[$i]=proc_open([PHP_BINARY,__DIR__.'/../fixtures/printify-connector/batch8/reserve-worker.php',$p],[1=>['pipe','w'],2=>['pipe','w']],$pipes[$i]);$out='';foreach($procs as $i=>$proc){$out.=stream_get_contents($pipes[$i][1]);fclose($pipes[$i][1]);fclose($pipes[$i][2]);self::assertSame(0,proc_close($proc));}self::assertSame(1,substr_count($out,'1'));self::assertSame('RESERVED',$s->inspect()['records']['a']['state']);}
 public function testLeaseCannotExpireEarlyOrRestoreSlot():void {[$s]=$this->store();$s->initialize();$s->transition('a','PREPARE',1,100);$s->transition('a','RESERVE',1,100);try{$s->transition('a','EXPIRE',1,119);self::fail('Lease still active');}catch(RuntimeException){self::assertSame('RESERVED',$s->inspect()['records']['a']['state']);}$s->transition('a','EXPIRE',1,120);$this->expectException(RuntimeException::class);$s->transition('a','RESERVE',1,121);}
 public function testRestartCannotRearmUsingCurrentGeneration():void {[$s,$p]=$this->store();$s->initialize();$s->transition('all','EMERGENCY',1,100);$s=new SyntheticRecoveryStore($p.'/state',$p.'/anchor');$this->expectException(RuntimeException::class);$s->transition('b','PREPARE',2,101);}
 public function testMissingJournalOrNamespaceWithOldCheckpointDenies():void {[$s,$p]=$this->store();$s->initialize();$blank=file_get_contents($p.'/state');$s->transition('a','PREPARE',1,100);file_put_contents($p.'/state',$blank);$this->expectException(RuntimeException::class);$s->inspect();}
}
